using System.Collections.ObjectModel;

namespace LibTmux;

/// <summary>Reports a process-transport failure.</summary>
public sealed class TmuxTransportException : LibTmuxException
{
    private readonly ReadOnlyCollection<string> _arguments;

    /// <summary>Initializes a transport exception whose dispatch state is unknown.</summary>
    public TmuxTransportException(
        string message,
        IReadOnlyList<string> arguments,
        Exception? innerException = null)
        : this(message, arguments, TmuxDispatchState.Unknown, innerException)
    {
    }

    /// <summary>Initializes a transport exception that knows whether tmux was started.</summary>
    /// <remarks>
    /// A transport failure is the one place the answer differs by cause. Rejecting
    /// a command for being too long, or failing to start the client at all, happens
    /// before tmux exists and is
    /// <see cref="TmuxDispatchState.NotDispatched"/>. A client that started and then
    /// died is <see cref="TmuxDispatchState.Unknown"/>, because tmux may well have
    /// acted before the pipe broke.
    /// </remarks>
    public TmuxTransportException(
        string message,
        IReadOnlyList<string> arguments,
        TmuxDispatchState dispatch,
        Exception? innerException = null)
        : base(message, dispatch, innerException)
    {
        ArgumentNullException.ThrowIfNull(arguments);
        _arguments = Array.AsReadOnly(arguments.ToArray());
    }

    /// <summary>Gets the logical tmux arguments.</summary>
    public IReadOnlyList<string> Arguments => _arguments;
}

src/LibTmux/Exceptions/TmuxUnsupportedOn.content:
namespace LibTmux;

/// <summary>Reports a command or feature that is unsafe or unavailable on the running tmux release.</summary>
/// <remarks>
/// <para>
/// Every refusal for a release reason raises this type or a subclass, so one
/// catch block covers a release that lacks a feature, a release that crashes
/// on a form, and a release that rejects an input other releases accept.
/// <see cref="TmuxVersionTooLowException" /> is the subclass for a plain
/// release floor. A typed call that leaves a flag out on an older release,
/// such as <c>Server.RefreshClientAsync</c> dropping <c>-l</c>, skips the
/// flag and raises nothing.
/// </para>
/// <para>
/// The library decides a refusal before anything is sent, so the exceptions it
/// raises carry <see cref="TmuxDispatchState.NotDispatched" /> in
/// <see cref="LibTmuxException.Dispatch" />, and sending the command again on
/// the same release repeats the refusal. An input that is invalid on every
/// release is not this type; it is an <see cref="ArgumentException" />.
/// </para>
/// </remarks>
public class TmuxUnsupportedOnReleaseException : LibTmuxException
{
    /// <summary>Initializes a release refusal.</summary>
    /// <param name="message">What was refused and why.</param>
    /// <param name="actualVersion">The running tmux release.</param>
    /// <param name="safeReleases">The releases where the command is safe, in words.</param>
    /// <param name="capabilityId">The id in <c>capabilities.json</c> that covers the refusal, if any.</param>
    /// <param name="command">The refused tmux command, if any.</param>
    /// <param name="innerException">The underlying failure, when any.</param>
    public TmuxUnsupportedOnReleaseException(
        string message,
        TmuxVersion actualVersion,
        string safeReleases,
        string? capabilityId = null,
        string? command = null,
        Exception? innerException = null)
        : this(message, actualVersion, safeReleases, capabilityId, command, TmuxDispatchState.Unknown, innerException)
    {
    }

    internal TmuxUnsupportedOnReleaseException(
        string message,
        TmuxVersion actualVersion,
        string safeReleases,
        string? capabilityId,
        string? command,
        TmuxDispatchState dispatch,
        Exception? innerException = null)
        : base(message, dispatch, innerException)
    {
        ActualVersion = actualVersion;
        SafeReleases = safeReleases;
        CapabilityId = capabilityId;
        Command = command;
    }

    /// <summary>Gets the running tmux release.</summary>
    public TmuxVersion ActualVersion { get; }

    /// <summary>Gets the releases where the command is safe, such as <c>3.4 or newer</c>.</summary>
    public string SafeReleases { get; }

    /// <summary>Gets the capability or workaround id in <c>capabilities.json</c>, or null when none covers the refusal.</summary>
    public string? CapabilityId { get; }

    /// <summary>Gets the refused tmux command, or null when the refusal is not about one command.</summary>
    public string? Command { get; }
}

src/LibTmux/Exceptions/TmuxVersionTooLow.content:
namespace LibTmux;

/// <summary>Reports an unsupported tmux version.</summary>
/// <remarks>
/// A report that names no release the library can rank, such as <c>master</c>,
/// is refused the same way with an <see cref="TmuxUnsupportedOnReleaseException.ActualVersion" />
/// that is not valid: the build may be newer than the minimum, but nothing can say so.
/// Catch <see cref="TmuxUnsupportedOnReleaseException" /> to cover refusals that
/// are not a plain floor as well.
/// </remarks>
public sealed class TmuxVersionTooLowException : TmuxUnsupportedOnReleaseException
{
    /// <summary>Initializes an unsupported-version exception.</summary>
    public TmuxVersionTooLowException(
        string message,
        TmuxVersion requiredVersion,
        TmuxVersion actualVersion,
        Exception? innerException = null)
        : base(message, actualVersion, SafeFrom(requiredVersion), null, null, innerException)
        => RequiredVersion = requiredVersion;

    internal TmuxVersionTooLowException(
        string message,
        TmuxVersion requiredVersion,
        TmuxVersion actualVersion,
        TmuxDispatchState dispatch,
        string? capabilityId = null,
        string? command = null,
        string? safeReleases = null)
        : base(message, actualVersion, safeReleases ?? SafeFrom(requiredVersion), capabilityId, command, dispatch)
        => RequiredVersion = requiredVersion;

    /// <summary>Gets the required tmux version.</summary>
    public TmuxVersion RequiredVersion { get; }

    private static string SafeFrom(TmuxVersion required) => $"{required} or newer";
}

