namespace LibTmux.Query;

/// <summary>Describes one field accepted by the current portable query schema.</summary>
/// <remarks>
/// Property paths describe built-in entity bindings. A schema-only field has no
/// property path. Uncaptured state still throws; it is not a nullable field value.
/// </remarks>
public sealed class QueryFieldDescriptor
{
    internal QueryFieldDescriptor(
        string wireName,
        QueryTarget target,
        QueryValueKind? valueKind,
        string? scalarPropertyPath,
        string? relationPropertyPath,
        QueryTarget? relatedTarget,
        QueryRelationCardinality? cardinality,
        SnapshotDepth? minimumSnapshotDepth,
        bool? isNullable,
        IReadOnlyList<string> operators)
    {
        WireName = wireName;
        Target = target;
        ValueKind = valueKind;
        ScalarPropertyPath = scalarPropertyPath;
        RelationPropertyPath = relationPropertyPath;
        RelatedTarget = relatedTarget;
        Cardinality = cardinality;
        MinimumSnapshotDepth = minimumSnapshotDepth;
        IsNullable = isNullable;
        Operators = Array.AsReadOnly(operators.ToArray());
    }

    /// <summary>Gets the field name used in query JSON.</summary>
    public string WireName { get; }

    /// <summary>Gets the target that owns this field.</summary>
    public QueryTarget Target { get; }

    /// <summary>Gets the scalar type, or null for a to-one relation.</summary>
    public QueryValueKind? ValueKind { get; }

    /// <summary>Gets the native scalar property path, or null without a scalar binding.</summary>
    /// <remarks>Collection counts end in <c>.Count</c>.</remarks>
    public string? ScalarPropertyPath { get; }

    /// <summary>Gets the native relation property path, or null without a relation binding.</summary>
    /// <remarks>Captured active values end in <c>.Value</c>.</remarks>
    public string? RelationPropertyPath { get; }

    /// <summary>Gets the related target kind, or null for a scalar-only field.</summary>
    public QueryTarget? RelatedTarget { get; }

    /// <summary>Gets the relation cardinality, or null for a scalar-only field.</summary>
    public QueryRelationCardinality? Cardinality { get; }

    /// <summary>Gets the field's minimum hierarchy capture depth, or null outside that hierarchy.</summary>
    /// <remarks>
    /// Clients and schema-only fields have no hierarchy capture depth. Nested
    /// predicates may need a deeper capture; read <see cref="QueryDocument.RequiredSnapshotDepth" />.
    /// </remarks>
    public SnapshotDepth? MinimumSnapshotDepth { get; }

    /// <summary>Gets whether the captured native scalar can be null, or null without a scalar binding.</summary>
    /// <remarks>The schema permits null equality comparisons even for nonnullable fields.</remarks>
    public bool? IsNullable { get; }

    /// <summary>Gets the accepted wire operation names for this field.</summary>
    /// <remarks>
    /// Comparison names populate <c>operator</c>; <c>any</c> and <c>all</c> populate
    /// <c>quantifier</c>. <c>regex</c> and <c>related</c> identify their node kinds.
    /// Boolean composition is independent of field operations.
    /// </remarks>
    public IReadOnlyList<string> Operators { get; }
}

src/LibTmux/Query/QueryNode.cs.content:
using System.Text.RegularExpressions;

namespace LibTmux.Query;

/// <summary>Names the tmux object a field or quantifier reads.</summary>
public enum QueryTarget
{
    /// <summary>A tmux session.</summary>
    Session = 0,

    /// <summary>A tmux window.</summary>
    Window = 1,

    /// <summary>A tmux pane.</summary>
    Pane = 2,

    /// <summary>A tmux client.</summary>
    Client = 3,
}

/// <summary>Names an ordering or equality comparison.</summary>
internal enum QueryComparison
{
    /// <summary>Operands are equal.</summary>
    Equal = 0,

    /// <summary>Operands differ.</summary>
    NotEqual = 1,

    /// <summary>The left operand is smaller.</summary>
    LessThan = 2,

    /// <summary>The left operand is not larger.</summary>
    LessThanOrEqual = 3,

    /// <summary>The left operand is larger.</summary>
    GreaterThan = 4,

    /// <summary>The left operand is not smaller.</summary>
    GreaterThanOrEqual = 5,
}

/// <summary>Names a string comparison, always ordinal.</summary>
/// <remarks>
/// tmux identifiers and names are byte strings, so culture-sensitive
/// comparison would make a query's meaning depend on the caller's locale.
/// </remarks>
internal enum QueryStringOperation
{
    /// <summary>Ordinal equality.</summary>
    EqualsOrdinal = 0,

    /// <summary>Case-insensitive ordinal equality.</summary>
    EqualsOrdinalIgnoreCase = 1,

    /// <summary>Ordinal prefix match.</summary>
    StartsWithOrdinal = 2,

    /// <summary>Ordinal suffix match.</summary>
    EndsWithOrdinal = 3,

    /// <summary>Ordinal substring match.</summary>
    ContainsOrdinal = 4,

    /// <summary>Case-insensitive ordinal prefix match.</summary>
    StartsWithOrdinalIgnoreCase = 5,

    /// <summary>Case-insensitive ordinal suffix match.</summary>
    EndsWithOrdinalIgnoreCase = 6,

    /// <summary>Case-insensitive ordinal substring match.</summary>
    ContainsOrdinalIgnoreCase = 7,
}

/// <summary>Names how a quantifier folds a relation.</summary>
internal enum QueryQuantifier
{
    /// <summary>True when at least one child matches; false when empty.</summary>
    Any = 0,

    /// <summary>True when every child matches; true when empty.</summary>
    All = 1,
}

/// <summary>One node of a translated query predicate.</summary>
internal abstract record QueryNode;

/// <summary>One literal value in a query predicate.</summary>
internal abstract record QueryConstant;

/// <summary>The absence of a value.</summary>
internal sealed record NullConstant : QueryConstant;

/// <summary>A boolean literal.</summary>
/// <param name="Value">The literal value.</param>
internal sealed record BooleanConstant(bool Value) : QueryConstant;

/// <summary>A 64-bit integer literal.</summary>
/// <param name="Value">The literal value.</param>
internal sealed record Int64Constant(long Value) : QueryConstant;

/// <summary>A string literal.</summary>
/// <param name="Value">The literal value.</param>
internal sealed record StringConstant(string Value) : QueryConstant;

/// <summary>A typed tmux identifier literal.</summary>
/// <param name="Target">The object the identifier names.</param>
/// <param name="Value">The identifier text.</param>
internal sealed record TypedIdConstant(QueryTarget Target, string Value) : QueryConstant;

/// <summary>A literal operand.</summary>
/// <param name="Value">The literal.</param>
internal sealed record ConstantNode(QueryConstant Value) : QueryNode;

/// <summary>A tmux format field operand.</summary>
/// <param name="Target">The object that owns the field.</param>
/// <param name="WireName">The tmux format token name.</param>
internal sealed record FieldNode(QueryTarget Target, string WireName) : QueryNode;

/// <summary>An ordering or equality comparison.</summary>
/// <param name="Operator">The comparison.</param>
/// <param name="Left">The left operand.</param>
/// <param name="Right">The right operand.</param>
internal sealed record ComparisonNode(
    QueryComparison Operator,
    QueryNode Left,
    QueryNode Right) : QueryNode;

/// <summary>An ordinal string comparison.</summary>
/// <param name="Operator">The string operation.</param>
/// <param name="Left">The left operand.</param>
/// <param name="Right">The right operand.</param>
internal sealed record StringNode(
    QueryStringOperation Operator,
    QueryNode Left,
    QueryNode Right) : QueryNode;

/// <summary>A constant-pattern regular expression match.</summary>
/// <param name="Input">The operand to match.</param>
/// <param name="Dialect">The regex dialect the pattern is written in.</param>
/// <param name="Pattern">The constant pattern.</param>
/// <param name="SemanticOptions">Options that change what the pattern means.</param>
internal sealed record RegexNode(
    QueryNode Input,
    string Dialect,
    string Pattern,
    RegexOptions SemanticOptions) : QueryNode;

/// <summary>A quantifier over a relation field.</summary>
/// <param name="Quantifier">How the relation is folded.</param>
/// <param name="Relation">The relation field to fold.</param>
/// <param name="Predicate">The predicate applied to each child.</param>
internal sealed record QuantifierNode(
    QueryQuantifier Quantifier,
    FieldNode Relation,
    QueryNode Predicate) : QueryNode;

internal sealed record RelatedNode(FieldNode Relation, QueryNode Predicate) : QueryNode;

/// <summary>The negation of one predicate.</summary>
/// <param name="Operand">The negated predicate.</param>
internal sealed record NotNode(QueryNode Operand) : QueryNode;

/// <summary>The conjunction of ordered operands.</summary>
/// <remarks>
/// Operand order is part of the value: two conjunctions with the same
/// operands in a different order are different documents, because the
/// wire form preserves order.
/// </remarks>
internal sealed record AndNode : QueryNode
{
    /// <summary>Initializes a conjunction.</summary>
    /// <param name="operands">The ordered operands.</param>
    public AndNode(IReadOnlyList<QueryNode> operands)
    {
        ArgumentNullException.ThrowIfNull(operands);
        Operands = [.. operands];
    }

    /// <summary>Gets the ordered operands.</summary>
    public IReadOnlyList<QueryNode> Operands { get; }

    /// <inheritdoc />
    public bool Equals(AndNode? other) => QueryNodeList.Equal(Operands, other?.Operands);

    /// <inheritdoc />
    public override int GetHashCode() => QueryNodeList.HashCode(Operands);
}

/// <summary>The disjunction of ordered operands.</summary>
/// <remarks>Operand order is part of the value, as for <see cref="AndNode" />.</remarks>
internal sealed record OrNode : QueryNode
{
    /// <summary>Initializes a disjunction.</summary>
    /// <param name="operands">The ordered operands.</param>
    public OrNode(IReadOnlyList<QueryNode> operands)
    {
        ArgumentNullException.ThrowIfNull(operands);
        Operands = [.. operands];
    }

    /// <summary>Gets the ordered operands.</summary>
    public IReadOnlyList<QueryNode> Operands { get; }

    /// <inheritdoc />
    public bool Equals(OrNode? other) => QueryNodeList.Equal(Operands, other?.Operands);

    /// <inheritdoc />
    public override int GetHashCode() => QueryNodeList.HashCode(Operands);
}

internal static class QueryNodeList
{
    // A record's synthesized equality compares list references, which would
    // make two structurally identical documents unequal.
    internal static bool Equal(IReadOnlyList<QueryNode> left, IReadOnlyList<QueryNode>? right) =>
        right is not null && left.SequenceEqual(right);

    internal static int HashCode(IReadOnlyList<QueryNode> operands)
    {
        HashCode hash = default;
        foreach (QueryNode operand in operands)
        {
            hash.Add(operand);
        }

        return hash.ToHashCode();
    }
}

